package com.ke.ticketsystemke.entity;
import jakarta.persistence.*;import java.time.*;
@Entity @Table(name="warranty_reminder_generation_runs")public class WarrantyReminderGenerationRun{@Id @GeneratedValue(strategy=GenerationType.IDENTITY)private Long id;@Column(nullable=false)private Instant startedAt;private Instant completedAt;@Column(nullable=false)private LocalDate businessDate;@Column(nullable=false,length=20)private String status;@Column(nullable=false)private int claimsScanned;@Column(nullable=false)private int remindersCreated;@Column(nullable=false)private int remindersUpdated;@Column(nullable=false)private int remindersResolved;@Column(nullable=false)private int failures;@Column(length=1000)private String errorSummary;public Long getId(){return id;}public Instant getStartedAt(){return startedAt;}public void setStartedAt(Instant v){startedAt=v;}public Instant getCompletedAt(){return completedAt;}public void setCompletedAt(Instant v){completedAt=v;}public LocalDate getBusinessDate(){return businessDate;}public void setBusinessDate(LocalDate v){businessDate=v;}public String getStatus(){return status;}public void setStatus(String v){status=v;}public int getClaimsScanned(){return claimsScanned;}public void setClaimsScanned(int v){claimsScanned=v;}public int getRemindersCreated(){return remindersCreated;}public void setRemindersCreated(int v){remindersCreated=v;}public int getRemindersUpdated(){return remindersUpdated;}public void setRemindersUpdated(int v){remindersUpdated=v;}public int getRemindersResolved(){return remindersResolved;}public void setRemindersResolved(int v){remindersResolved=v;}public int getFailures(){return failures;}public void setFailures(int v){failures=v;}public String getErrorSummary(){return errorSummary;}public void setErrorSummary(String v){errorSummary=v;}}
